import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const MyOrders = () => {
  const [orders, setOrders] = useState([]);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/orders/user/${userId}`)
      .then((res) => res.json())
      .then((data) => setOrders(data))
      .catch((err) => console.error("Error loading orders:", err));
  }, [userId]);

  const cancelOrder = async (orderId) => {
    if (!window.confirm("Are you sure you want to cancel this order?")) return;

    try {
      const res = await fetch(`${API_BASE_URL}/api/orders/${orderId}`, {
        method: "DELETE",
      });
      if (res.ok) {
        setOrders(orders.filter((order) => order.id !== orderId));
      } else {
        alert("Failed to cancel order.");
      }
    } catch (err) {
      console.error("Cancel error:", err);
      alert("Something went wrong.");
    }
  };

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="cart-container">
        <div className="cart-left">
          <h2>My Orders</h2>
          {orders.length === 0 ? (
            <p>You haven’t placed any orders yet.</p>
          ) : (
            orders.map((order, idx) => (
              <div key={idx} className="order-card">
                <div className="order-header">
                  <p><strong>Order #{order.id}</strong></p>
                  <p><strong>Delivery Date:</strong> {new Date(order.delivery_date).toDateString()}</p>
                  <p><strong>Total:</strong> ${parseFloat(order.total).toFixed(2)}</p>
                  <button onClick={() => cancelOrder(order.id)} className="cancel-btn">
                    Cancel Order
                  </button>
                </div>

                <div className="order-items">
                  {order.items.map((item, i) => (
                    <div key={i} className="order-item">
                      <p><strong>{item.title}</strong></p>
                      <p>${parseFloat(item.price).toFixed(2)} — {item.condition}</p>
                    </div>
                  ))}
                </div>
              </div>
            ))
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default MyOrders;
